window.kbPageData["views/entry/k-3c751ecd149b9985"] = {"key":"entry/k-3c751ecd149b9985","state":{"route":"entry/k-3c751ecd149b9985"},"node":{"id":"k-3c751ecd149b9985","mode":"k","title":"外交思想","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["观点与论证"],"出处性质":["理论手册"],"学科":["政治理论"],"来源主题":["新时代中国特色社会主义思想"],"资料类别":["非时政"]},"directorySummary":"1.十个坚持\n2018 年 6 月 22 日至 23 日，中央外事工作会议确立习近平外交思想的指导地位，并用\n“十个坚持”阐释习近平外交思想的丰富内涵。即：\n（1）坚持以维护党中央权威为统领加强党对对外工作的集中统一领导；\n（2）坚持以实现中华民族伟大复兴为使命推进中国特色大国外交；\n（3）坚持以维…","sources":[{"id":"11334b77ee634395","label":"外交思想","topic":"新时代中国特色社会主义思想","category":"非时政","text":"1.十个坚持\n2018 年 6 月 22 日至 23 日，中央外事工作会议确立习近平外交思想的指导地位，并用\n“十个坚持”阐释习近平外交思想的丰富内涵。即：\n（1）坚持以维护党中央权威为统领加强党对对外工作的集中统一领导；\n（2）坚持以实现中华民族伟大复兴为使命推进中国特色大国外交；\n（3）坚持以维护世界和平、促进共同发展为宗旨推动构建人类命运共同体；\n（4）坚持以中国特色社会主义为根本增强战略自信；\n（5）坚持以共商共建共享为原则推动“一带一路”建设；\n（6）坚持以相互尊重、合作共赢为基础走和平发展道路；\n（7）坚持以深化外交布局为依托打造全球伙伴关系；\n（8）坚持以公平正义为理念引领全球治理体系改革；\n（9）坚持以国家核心利益为底线维护国家主权、安全、发展利益；\n（10）坚持以对外工作优良传统和时代特征相结合为方向塑造中国外交独特风范。\n2.六个必须\n2023 年 12 月 27 日至 28 日，中央外事工作会议系统总结新时代中国特色大国外交的\n历史性成就和宝贵经验。历史性成就涵盖十个方面，排在第一的是“创立和发展了习近平外\n交思想”。\n会议将新时代外交工作的宝贵经验总结为“六个必须”，即：（1）必须做到坚持原则，\n（2）必须体现大国担当，\n（3）必须树立系统观念，\n（4）必须坚持守正创新，\n（5）必须发扬\n斗争精神，（6）必须发挥制度优势。","source":{"doc":"3ccc56f4000d1642c2d1","first":24,"last":25,"page":24,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-3c751ecd149b9985":[]}};
